<!--
 * 站内通知发送表单组件
 *
 * @path apps/message-web/src/views/notification/notification-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：发送通知表单（NotificationSendDTO）提交 send()。
-->
<script lang="ts" setup>
/**
 * 站内通知（发送表单组件）
 * <p>消费后端契约 NotificationController#send（src/api/notification.ts，auto-generated by bash/gen-contract.py）：
 * 按 NotificationSendDTO 字段（receiverId(s)/title/content/level/category/priority/bizType 等）填写，
 * 提交成功后 emit('success') 并关闭弹窗。通知仅存在「发送」语义，无编辑。
 *
 * <p>备注：后端 @提及（mentionUserIds）仅存在于通知记录模型 MsgNotificationDTO（由评论等业务产生），
 * NotificationSendDTO 无该字段，故发送表单不提供提及输入；提及信息在列表页（index.vue）消费展示。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import { ElForm, ElFormItem, ElInput, ElMessage, ElOption, ElSelect } from 'element-plus';
import { reactive, ref } from 'vue';

import { send } from '#/api/notification';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();

/** 发送通知表单状态（字段对应 NotificationSendDTO，receiverListText 拆分后映射 receiverIds） */
interface NotificationFormState {
  receiverListText: string;
  title: string;
  content: string;
  level: string;
  category: string;
  priority: string;
  senderId: string;
  bizType: string;
  actionUrl: string;
  actionText: string;
}

const formData = reactive<NotificationFormState>({
  receiverListText: '',
  title: '',
  content: '',
  level: 'INFO',
  category: '',
  priority: '',
  senderId: '',
  bizType: '',
  actionUrl: '',
  actionText: '',
});

const rules = {
  receiverListText: [{ required: true, message: '请输入接收者', trigger: 'blur' }],
  title: [{ required: true, message: '请输入标题', trigger: 'blur' }],
  content: [{ required: true, message: '请输入内容', trigger: 'blur' }],
};

/** 文本域按换行/逗号拆分接收者列表 */
function parseReceiverIds(): string[] {
  return formData.receiverListText
    .split(/[\n,;，；]/)
    .map((item) => item.trim())
    .filter((item) => item !== '');
}

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    Object.assign(formData, {
      receiverListText: '',
      title: '',
      content: '',
      level: 'INFO',
      category: '',
      priority: '',
      senderId: '',
      bizType: '',
      actionUrl: '',
      actionText: '',
    });
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      await send({
        receiverIds: parseReceiverIds(),
        title: formData.title,
        content: formData.content,
        level: formData.level || undefined,
        category: formData.category || undefined,
        priority: formData.priority || undefined,
        senderId: formData.senderId || undefined,
        bizType: formData.bizType || undefined,
        actionUrl: formData.actionUrl || undefined,
        actionText: formData.actionText || undefined,
      });
      ElMessage.success('通知发送成功');
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});
</script>
<template>
  <Modal title="发送通知">
    <ElForm ref="formRef" :model="formData" :rules="rules" label-width="100px" label-position="right">
      <ElFormItem label="接收者" prop="receiverListText">
        <ElInput
          v-model="formData.receiverListText"
          type="textarea"
          :rows="3"
          placeholder="每行一个接收者ID，支持逗号/分号/换行分隔"
        />
      </ElFormItem>
      <ElFormItem label="标题" prop="title">
        <ElInput v-model="formData.title" placeholder="请输入标题" />
      </ElFormItem>
      <ElFormItem label="内容" prop="content">
        <ElInput v-model="formData.content" type="textarea" :rows="3" placeholder="请输入内容" />
      </ElFormItem>
      <ElFormItem label="级别" prop="level">
        <ElSelect v-model="formData.level" placeholder="请选择级别">
          <ElOption label="提示" value="INFO" />
          <ElOption label="警告" value="WARN" />
          <ElOption label="错误" value="ERROR" />
        </ElSelect>
      </ElFormItem>
      <ElFormItem label="分类" prop="category">
        <ElInput v-model="formData.category" placeholder="请输入分类（可为空）" />
      </ElFormItem>
      <ElFormItem label="优先级" prop="priority">
        <ElSelect v-model="formData.priority" placeholder="请选择优先级（可为空）" clearable>
          <ElOption label="高" value="HIGH" />
          <ElOption label="中" value="MEDIUM" />
          <ElOption label="低" value="LOW" />
        </ElSelect>
      </ElFormItem>
      <ElFormItem label="业务类型" prop="bizType">
        <ElInput v-model="formData.bizType" placeholder="请输入业务类型（可为空）" />
      </ElFormItem>
      <ElFormItem label="跳转链接" prop="actionUrl">
        <ElInput v-model="formData.actionUrl" placeholder="请输入跳转链接（可为空）" />
      </ElFormItem>
      <ElFormItem label="跳转文案" prop="actionText">
        <ElInput v-model="formData.actionText" placeholder="请输入跳转文案（可为空）" />
      </ElFormItem>
    </ElForm>
  </Modal>
</template>